INSERT INTO `jpb_log_notif` (`id`, `category`, `title`, `send`, `message`, `status`, `date`, `user_id`, `user_2nd`) VALUES (659, 'email', 'Invoice Information', 'demoaccount@jpbuana.com', '\n<div style=\"max-width:600px;margin:0 auto;font-family:\'Helvetica Neue\',\'Helvetica\',Helvetica,Arial,sans-serif\">\n    <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"100%\" style=\"margin:auto;background:transparent; border: none\">\n        <tbody>\n            <tr style=\"margin:0;padding:0\">\n                <td style=\"margin:0;padding:0\"></td>\n                <td style=\"display:block!important;max-width:600px!important;min-width:600px!important;clear:both!important;margin:0 auto;padding:0;background-color:transparent\">\n                    <div style=\"min-width:600px;display:block;border-collapse:collapse;margin:0 auto;\">\n                        <table style=\"max-width:100%;border-spacing:0;width:100%;background-color:transparent;margin:0; padding:20px\" cellspacing=\"0\" cellpadding=\"0\">\n                            <tbody>\n                                <tr>\n                                    <td>\n                                        <img src=\"https://jpbuana.com/dhaassets/backend/img/logo.png\" height=\"40\" alt=\"Company Name\" />\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n    \n    <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"100%\" style=\"margin:auto;background-color:#ffffff;border: 1px solid #e7e7e7;\">\n        <tbody>\n            <tr style=\"margin:0;padding:0\">\n                <td style=\"display:block!important;max-width:600px!important;min-width:600px!important;clear:both!important;background-color:transparent;margin:0 auto;padding: 20px\">\n    