  `birthdate` date DEFAULT NULL,
  `gender` varchar(255) DEFAULT NULL,
  `idcard` varchar(50) DEFAULT NULL,
  `npwp` varchar(50) DEFAULT '',
  `country` varchar(10) DEFAULT NULL,
