  `bill` varchar(20) DEFAULT NULL,
  `bill_name` varchar(255) DEFAULT NULL,
  `photo` text DEFAULT NULL,
  `idcard_img` text DEFAULT NULL,
  `qrcode_img` varchar(200) DEFAULT NULL,
  `total_omzet` double NOT NULL,
  `package_omzet` double NOT NULL,
  `rank` varchar(30) DEFAULT NULL,
  `referral_code` varchar(20) DEFAULT NULL,
