  `as_stockist_pusat` tinyint(1) NOT NULL,
  `stockist_name` varchar(100) DEFAULT NULL,
  `stockist_province` smallint(6) DEFAULT NULL,
  `stockist_district` smallint(6) DEFAULT NULL,
  `stockist_subdistrict` smallint(6) DEFAULT NULL,
  `stockist_village` varchar(100) DEFAULT NULL,
  `stockist_address` text DEFAULT NULL,
  `to_stockist` bigint(20) NOT NULL,
  `shop_invoice` smallint(6) NOT NULL,
  `shop_uniquecode` smallint(6) NOT NULL,
