  `agree_ethic` tinyint(1) NOT NULL DEFAULT 0,
  `change_password` smallint(6) NOT NULL,
  `last_login` datetime DEFAULT NULL,
  `member_hu` bigint(20) NOT NULL,
  `is_ro` int(11) NOT NULL,
