  UNIQUE KEY `memberunique` (`username`) USING BTREE,
  UNIQUE KEY `parentunique` (`parent`,`position`) USING BTREE,
  KEY `memberuid` (`username`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE,
  KEY `sponsor` (`sponsor`) USING BTREE,
  KEY `parent` (`parent`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
